<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { apiRequest } from './api'
const content = ref(''); const exists = ref(false); const path = ref(''); const updatedAt = ref<number | null>(null); const error = ref(''); const loading = ref(false)
const query = ref(''); const level = ref('all'); const newestFirst = ref(true); const autoRefresh = ref(true); let timer: number | undefined
const lines = computed(() => { const source = content.value.split('\n'); const ordered = newestFirst.value ? source.reverse() : source; return ordered.filter((line) => (level.value === 'all' || line.toUpperCase().includes(level.value.toUpperCase())) && line.toLowerCase().includes(query.value.toLowerCase())) })
async function refresh() { loading.value = true; try { const result = await apiRequest<{ exists: boolean; path: string; content: string; updated_at: number | null }>('/console/debug/backend-logs?lines=200'); exists.value = result.exists; path.value = result.path; content.value = result.content; updatedAt.value = result.updated_at; error.value = '' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load backend logs.' } finally { loading.value = false } }
function schedule() { if (timer) window.clearInterval(timer); if (autoRefresh.value) timer = window.setInterval(() => void refresh(), 3_000) }
function copy() { void navigator.clipboard.writeText(lines.value.join('\n')) }
onMounted(() => { void refresh(); schedule() }); onBeforeUnmount(() => { if (timer) window.clearInterval(timer) })
</script>
<template><section class="settings-page"><header class="settings-heading"><div><p class="eyebrow">SETTINGS</p><h1>Debug</h1><p>Inspect the bounded backend daemon log for troubleshooting.</p></div><button @click="refresh">Refresh logs</button></header><p v-if="error" class="inline-error">{{ error }}</p><div class="settings-card"><div class="environment-actions"><label>Level<select v-model="level"><option value="all">All</option><option value="error">Error</option><option value="warn">Warning</option><option value="info">Info</option><option value="debug">Debug</option></select></label><label>Search<input v-model="query" placeholder="Search backend logs" /></label><label class="skills-checkbox"><input v-model="newestFirst" type="checkbox" />Newest first</label><label class="skills-checkbox"><input v-model="autoRefresh" type="checkbox" @change="schedule" />Auto refresh</label><button @click="copy">Copy visible logs</button></div><p class="muted">{{ exists ? `Log file: ${path}` : 'Backend log file has not been created.' }}<template v-if="updatedAt"> · Updated {{ new Date(updatedAt * 1000).toLocaleString() }}</template></p><pre class="debug-log">{{ loading ? 'Loading…' : lines.join('\n') || 'No matching log lines.' }}</pre></div></section></template>
